selector_to_html = {"a[href=\"#pyskyfire.pump.diffuser.VanedDiffuser.__repr__\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.pump.diffuser.VanedDiffuser.__repr__\">\n<span class=\"sig-name descname\"><span class=\"pre\">__repr__</span></span><span class=\"sig-paren\">(</span><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#pyskyfire.pump.diffuser.VanedDiffuser\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.pump.diffuser.VanedDiffuser\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.pump.diffuser.</span></span><span class=\"sig-name descname\"><span class=\"pre\">VanedDiffuser</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">flow</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">d2</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">b2</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">u2</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">c2u</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">impeller_blade_count</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">H</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">nq</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">rho</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">vane_count</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">gap_ratio</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">inlet_width_ratio</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">1.15</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">outer_diameter_ratio</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">length_ratio</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">outlet_width_ratio</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">1.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">throat_factor</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">deceleration</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">vane_thickness_ratio</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.012</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">roughness</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">rotation</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">COUNTERCLOCKWISE</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>A vaned radial diffuser designed from the impeller it follows.</p><p>Build one with <a class=\"reference internal\" href=\"#pyskyfire.pump.diffuser.VanedDiffuser.from_impeller\" title=\"pyskyfire.pump.diffuser.VanedDiffuser.from_impeller\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">from_impeller()</span></code></a>. The direct constructor takes the\nimpeller outlet as numbers: <code class=\"docutils literal notranslate\"><span class=\"pre\">flow</span></code> through the impeller [m\u00b3/s], its\noutlet diameter <code class=\"docutils literal notranslate\"><span class=\"pre\">d2</span></code> and width <code class=\"docutils literal notranslate\"><span class=\"pre\">b2</span></code> [m], tip speed <code class=\"docutils literal notranslate\"><span class=\"pre\">u2</span></code> and outlet\nswirl <code class=\"docutils literal notranslate\"><span class=\"pre\">c2u</span></code> [m/s], blade count, speed <code class=\"docutils literal notranslate\"><span class=\"pre\">n</span></code> [rpm], head <code class=\"docutils literal notranslate\"><span class=\"pre\">H</span></code> [m] (the\nhead at the impeller outlet, used for the gap and exit-energy rules),\nspecific speed <code class=\"docutils literal notranslate\"><span class=\"pre\">nq</span></code>, density <code class=\"docutils literal notranslate\"><span class=\"pre\">rho</span></code> [kg/m\u00b3] and <code class=\"docutils literal notranslate\"><span class=\"pre\">rotation</span></code>.</p><p>Design inputs, with G\u00fclich\u2019s ranges:</p></dd>", "a[href=\"#pyskyfire-pump-diffuser-vaneddiffuser\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.pump.diffuser.VanedDiffuser<a class=\"headerlink\" href=\"#pyskyfire-pump-diffuser-vaneddiffuser\" title=\"Link to this heading\">\u00b6</a></h1>", "a[href=\"#pyskyfire.pump.diffuser.VanedDiffuser.solve\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.pump.diffuser.VanedDiffuser.solve\">\n<span class=\"sig-name descname\"><span class=\"pre\">solve</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">inlet_state</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">mass_flow</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">transport</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Total pressure lost from impeller outlet to channel exit, Table 3.8 (2).</p><p>The swirl entering is the design swirl and the through-flow follows the\nmass flow, as the volute treats it. Density and viscosity are taken at\nthe inlet; the flow is a liquid.</p></dd>", "a[href=\"#pyskyfire.pump.diffuser.VanedDiffuser.build_geometry\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.pump.diffuser.VanedDiffuser.build_geometry\">\n<span class=\"sig-name descname\"><span class=\"pre\">build_geometry</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">chord_points</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">65</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Resolve the vane surfaces and walls for display. Returns and stores them.</p></dd>", "a[href=\"#pyskyfire.pump.diffuser.VanedDiffuser.from_impeller\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.pump.diffuser.VanedDiffuser.from_impeller\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">classmethod</span></span><span class=\"w\"> </span></span><span class=\"sig-name descname\"><span class=\"pre\">from_impeller</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">impeller</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">rho</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"o\"><span class=\"pre\">**</span></span><span class=\"n\"><span class=\"pre\">design</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Design the diffuser for an <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">Impeller</span></code>\u2019s outlet.</p><p>The swirl is the impeller\u2019s slip prediction on its mean streamline, and\nthe head its outlet head. <code class=\"docutils literal notranslate\"><span class=\"pre\">rho</span></code> defaults to the impeller\u2019s.</p></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
